import{_ as e,o as a,c as o,ag as d}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"调频","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/modules/frequency_modulator/index.md","filePath":"v0.4.0-alpha/modules/frequency_modulator/index.md"}'),r={name:"v0.4.0-alpha/modules/frequency_modulator/index.md"};function i(l,t,n,c,h,s){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="调频" tabindex="-1">调频 <a class="header-anchor" href="#调频" aria-label="Permalink to &quot;调频&quot;">​</a></h1><p>适用：v0.4.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>frequency_modulator</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>把实数输入转换成复数调频信号。输入控制每个采样的相位增量，输出为累计相位对应的 <code>cos(φ)+j sin(φ)</code>，模长约为 1。</p><p>它将输入变化编码到相位的变化速度中。输入幅度增大时，相位通常转得更快，输出包络不会因此按比例增大。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>信号源.out → 调频.in → 正交解调.in</code>。也可将 <code>调频.out</code> 分支接入幅相分解，分别观察幅度和相位。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（复数输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p><code>sensitivity</code> 是灵敏度，单位为 <strong>rad／采样／单位输入</strong>，不是 Hz。设灵敏度为 k，输入为 x，每个采样的相位增量为 <code>k×x</code>。对于恒定输入 a，对应频率按 <code>k×a×Fs/(2π)</code> 换算，其中 Fs 是实际输入采样率。</p><p>灵敏度允许负值和 0，按有限 float32 值交给原生模块；实际值以原生回读为准。负灵敏度会反转相位转动方向；灵敏度为 0 时不再增加相位。每采样相位转动过大时会发生离散时间频率混叠，不能仅凭这个公式区分相差整数倍 Fs 的频率。</p><p>本模块只处理标量，输入、输出 item 一一对应，采样率不变。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>灵敏度（rad／采样／单位输入）<br><code>sensitivity</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>sensitivity</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线应用灵敏度后会回读实际值，并保留此前累计相位。把灵敏度改为 0 会停在当前相位，不保证输出变成 <code>1+j0</code>；回执也不代表能精确定位每个样本的切换边界。</p><p>重新准备会创建新的调频状态，从零初相开始。首个输出先累计首个输入的相位增量，再生成复数值，因此首项不一定是 <code>1+j0</code>。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="调频、幅相、正交解调与二值-bpsk-映射" tabindex="-1">调频、幅相、正交解调与二值 BPSK 映射 <a class="header-anchor" href="#调频、幅相、正交解调与二值-bpsk-映射" aria-label="Permalink to &quot;调频、幅相、正交解调与二值 BPSK 映射&quot;">​</a></h3><p><a href="../../../downloads/v0.4.0-alpha/modulation-chain.cnsproj" download>下载 modulation-chain.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>调频、幅相、正交解调与二值 BPSK 映射</p><ul><li>Fs=4096，常量 1 经 sensitivity=π/8 调频得到 +256 Hz、模长 1 的复相量，首项先累加。幅相输出主值相位；gain=8/π 解调首项为 0、后续约 1。二值判决对零和正值均输出索引 1，按生产 BPSK 点表映射。码元 OUT 固定 M2，不生成模拟幅度频谱。</li></ul><p>调频与判决示例使用 4096 Hz 采样率、常量输入 1 和灵敏度 π/8。观察 <code>out</code> 的复数频谱，预期谱峰位于约 +256 Hz；接到幅相分解后，幅度应约为 1，相位按每采样约 π/8 前进并绕回。</p><p>示例中的正交解调器使用倍率 8/π，预期首项为 0，后续解调值约为 1。比较在线改参和停止后重新准备，可以区分保留累计相位与重置初相这两种行为。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>输入为 0，输出为什么不为 0？</strong> 输入为 0 表示相位不再前进，输出仍是当前相位上的单位复数。</p><p><strong>灵敏度直接填 256，能得到 256 Hz 吗？</strong> 不能。先根据实际 Fs 和输入幅度换算每采样相位增量；灵敏度的单位不是 Hz。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/08-fm/">08 从数值到调频再解调</a></li></ul>',34)])])}const b=e(r,[["render",i]]);export{u as __pageData,b as default};
